def Strongest_Extension(class_name, extensions):
    strongest_extension = extensions[0]
    max_strength = len([char for char in strongest_extension if char.isupper]) - len([char for char in strongest_extension if char.islower])

    for extension in extensions[1:]:
        strength = len([char for char in extension if char.isupper]) - len([char for char in extension if char.islower])

        if strength > max_strength:
            max_strength = strength
            strongest_extension = extension

    return class_name + '.' + strongest_extension

def Strongest_Extension(class_name, extensions):
    strongest_extension = max(extensions, key=lambda x: sum(1 for c in x if c.isupper()) - sum(1 for c in x if c.islower()))
    return f"{class_name}.{strongest_extension}"

